import cv2

cap = cv2.VideoCapture("/dev/video2", cv2.CAP_V4L2)

if not cap.isOpened():
    print("Camera failed")
    exit()

while True:
    ret, frame = cap.read()

    if not ret:
        print("Camera failed")
        break

    cv2.imshow("iPhone", frame)

    if cv2.waitKey(1) & 0xFF == 27:
        break

cap.release()
cv2.destroyAllWindows()